    $read=@($samples|Where-Object {$_.readingHold-and$_.useVariant-eq6-and[double]$_.useWeight-gt.5});$row.readingSamples=$read.Count
    $row.sourceLogics=@($samples|ForEach-Object {$_.sourceLogic}|Sort-Object -Unique)
